import { getAddressEncoder } from "@solana/kit";
export function writeU16LE(buf, offset, value) {
    const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
    view.setUint16(offset, value, true);
    return offset + 2;
}
export function writeU32LE(buf, offset, value) {
    const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
    view.setUint32(offset, value, true);
    return offset + 4;
}
export function writeU64LE(buf, offset, value) {
    const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
    view.setBigUint64(offset, value, true);
    return offset + 8;
}
export function writeAddress(buf, offset, addr) {
    buf.set(getAddressEncoder().encode(addr), offset);
    return offset + 32;
}
